-- AI Insight (2026-11-20): short spending suggestions generated by the `ai-insight` Edge Function.
-- Applied on top of 0001–0007: run this file once in the Supabase SQL Editor.
--
-- Anyone in the household can generate one, up to 5 a day per household (IST), to cap API cost.
-- The Edge Function claims a slot first (claim_ai_insight), calls Claude, then saves the result
-- (complete_ai_insight). Both run with the caller's own login, so RLS and these checks apply.

create table if not exists public.ai_insights (
  id           uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  year         int not null check (year between 2000 and 2100),
  month        int not null check (month between 1 and 12),
  status       text not null default 'pending' check (status in ('pending', 'done', 'failed')),
  -- {category, headline, tips[], funny, benchmark_note, sources[{title,url}]}
  content      jsonb,
  error        text check (error is null or char_length(error) <= 300),
  created_by   uuid not null references public.profiles (id),
  created_at   timestamptz not null default now(),
  completed_at timestamptz
);
create index if not exists ai_insights_household on public.ai_insights (household_id, created_at desc);

alter table public.ai_insights enable row level security;
drop policy if exists ai_insights_select on public.ai_insights;
create policy ai_insights_select on public.ai_insights for select to authenticated
  using (public.is_household_member(household_id));
revoke all on public.ai_insights from anon, authenticated;
grant select on public.ai_insights to authenticated;

create or replace function public.ai_insight_daily_limit() returns int
language sql immutable as $$ select 5 $$;

-- Insights used today (IST): finished ones, plus ones still running from the last 10 minutes.
create or replace function public.ai_insights_used_today(p_household uuid) returns int
language sql stable security definer set search_path = public as $$
  select count(*)::int from ai_insights
  where household_id = p_household and is_household_member(p_household)
    and (created_at at time zone 'Asia/Kolkata')::date = ist_today()
    and (status = 'done' or (status = 'pending' and created_at > now() - interval '10 minutes'))
$$;

-- Reserves one of today's slots. Returns the new insight id.
create or replace function public.claim_ai_insight(p_household uuid, p_year int, p_month int) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid;
begin
  if not is_household_member(p_household) then
    raise exception 'You are not a member of this household.' using errcode = '42501';
  end if;
  -- Serialise claims per household so two taps can't both take the last slot.
  perform pg_advisory_xact_lock(hashtext('ai_insight:' || p_household::text));
  if ai_insights_used_today(p_household) >= ai_insight_daily_limit() then
    raise exception 'The household has used today''s % AI Insights. Try again tomorrow.', ai_insight_daily_limit()
      using errcode = 'P0001';
  end if;
  insert into ai_insights (household_id, year, month, created_by)
  values (p_household, p_year, p_month, auth.uid())
  returning id into v_id;
  return v_id;
end
$$;

-- Saves the result (or the failure) of a claimed insight. Only its creator, only while pending.
create or replace function public.complete_ai_insight(p_id uuid, p_content jsonb, p_error text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_content is not null and jsonb_typeof(p_content) <> 'object' then
    raise exception 'Invalid insight.' using errcode = '22023';
  end if;
  if p_content is not null and length(p_content::text) > 4000 then
    raise exception 'Insight too long.' using errcode = '22023';
  end if;
  update ai_insights
  set status = case when p_content is not null then 'done' else 'failed' end,
      content = p_content, error = left(p_error, 300), completed_at = now()
  where id = p_id and created_by = auth.uid() and status = 'pending'
    and created_at > now() - interval '10 minutes';
  if not found then
    raise exception 'This insight can no longer be saved.' using errcode = 'P0002';
  end if;
end
$$;

revoke all on function public.ai_insights_used_today(uuid) from public, anon;
revoke all on function
  public.claim_ai_insight(uuid, int, int),
  public.complete_ai_insight(uuid, jsonb, text)
  from public, anon;
grant execute on function
  public.ai_insight_daily_limit(),
  public.ai_insights_used_today(uuid),
  public.claim_ai_insight(uuid, int, int),
  public.complete_ai_insight(uuid, jsonb, text)
  to authenticated;
